'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { useAuth } from '@/lib/auth/context';
import { Clock, FileText, DollarSign } from 'lucide-react';

const ILPEA_LOGO =
  'data:image/png;base64,';

export default function LoginPage() {
  const [employeeId, setEmployeeId] = useState('');
  const [pin, setPin] = useState('');
  const [error, setError] = useState('');
  const [loading, setLoading] = useState(false);
  const { signIn } = useAuth();
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');
    if (!employeeId || !pin) {
      setError('กรุณากรอกรหัสพนักงานและ PIN');
      return;
    }
    if (pin.length !== 6) {
      setError('PIN ต้องมี 6 หลัก');
      return;
    }
    setLoading(true);
    try {
      await signIn(employeeId.toUpperCase(), pin);
      router.push('/dashboard');
    } catch (err: any) {
      setError(err.message || 'เข้าสู่ระบบไม่สำเร็จ');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen flex">
      {/* ซ้าย — แบนเนอร์ */}
      <div className="hidden lg:flex relative w-1/2 flex-col justify-between p-12 overflow-hidden bg-gradient-to-br from-white via-blue-50/60 to-blue-100">
        {/* decorative abstract shapes — purely visual, no logo/branding assets */}
        <div className="pointer-events-none absolute -top-28 -right-20 w-[420px] h-[420px] rounded-full bg-gradient-to-br from-blue-200/50 to-blue-300/30 blur-3xl" />
        <div className="pointer-events-none absolute top-1/2 -left-16 w-64 h-64 rounded-full bg-blue-100/60 blur-3xl" />
        <svg
          className="pointer-events-none absolute bottom-0 left-0 w-full text-blue-50"
          viewBox="0 0 800 200"
          preserveAspectRatio="none"
          fill="currentColor"
        >
          <path d="M0,120 C200,180 400,60 800,140 L800,200 L0,200 Z" />
        </svg>

        {/* โลโก้ — ตรึงมุมซ้ายบน */}
        <div className="relative">
          <img
            src={ILPEA_LOGO}
            alt="ILPEA Thailand"
            className="h-20 w-auto object-contain"
          />
        </div>

        {/* หัวข้อ + feature list เป็นกลุ่มเดียวกัน อยู่กึ่งกลางที่เหลือ */}
        <div className="relative flex-1 flex flex-col justify-center gap-10 -mt-20">
          <div>
            <h1 className="text-4xl font-bold text-slate-900 leading-tight">
              ระบบ HR
              <br />
              <span className="text-blue-600">อัจฉริยะ</span>
            </h1>
            <div className="w-14 h-1 bg-blue-600 rounded-full mt-4" />
            <p className="text-slate-500 mt-4 text-lg">
              ILPEA Thailand Co., Ltd.
            </p>

            <div className="mt-10 space-y-4">
              {[
                { icon: Clock, text: 'ลงเวลาเข้า-ออกงาน' },
                { icon: FileText, text: 'ยื่นและอนุมัติการลา' },
                { icon: DollarSign, text: 'ดูสลิปเงินเดือน' },
              ].map(({ icon: Icon, text }) => (
                <div
                  key={text}
                  className="flex items-center gap-3 text-slate-600"
                >
                  <div className="w-9 h-9 bg-blue-600 rounded-xl flex items-center justify-center text-white shadow-sm shadow-blue-600/20">
                    <Icon size={16} />
                  </div>
                  <span className="font-medium">{text}</span>
                </div>
              ))}
            </div>
          </div>
        </div>

        <p className="relative text-slate-400 text-sm">© 2025 ILPEA Thailand</p>
      </div>

      {/* ขวา — ฟอร์ม Login */}
      <div className="w-full lg:w-1/2 flex items-center justify-center p-8 bg-white">
        <div className="w-full max-w-sm">
          {/* Logo มือถือ */}
          <div className="lg:hidden text-center mb-8">
            <img
              src={ILPEA_LOGO}
              alt="ILPEA Thailand"
              className="h-20 w-auto object-contain mx-auto mb-3"
            />
          </div>

          <div className="mb-10">
            <h2 className="text-3xl font-bold text-gray-900 tracking-tight">
              ยินดีต้อนรับ
            </h2>
            <p className="text-gray-500 mt-2">
              กรุณาเข้าสู่ระบบเพื่อดำเนินการต่อ
            </p>
          </div>

          <form onSubmit={handleSubmit} className="space-y-5">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                รหัสพนักงาน
              </label>
              <div className="relative">
                <span className="absolute left-4 top-1/2 -translate-y-1/2 text-gray-400 text-sm font-mono"></span>
                <input
                  type="text"
                  value={employeeId}
                  onChange={(e) => setEmployeeId(e.target.value.toUpperCase())}
                  placeholder="EMP001"
                  maxLength={10}
                  className="w-full pl-8 pr-4 py-3 bg-white border border-gray-200 rounded-xl text-gray-900 placeholder-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent text-base font-mono tracking-wider shadow-sm"
                  disabled={loading}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-2">
                PIN 6 หลัก
              </label>
              <input
                type="password"
                value={pin}
                onChange={(e) => {
                  const val = e.target.value.replace(/\D/g, '');
                  if (val.length <= 6) setPin(val);
                }}
                placeholder="• • • • • •"
                maxLength={6}
                inputMode="numeric"
                className="w-full px-4 py-3 bg-white border border-gray-200 rounded-xl text-gray-900 placeholder-gray-300 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent text-center text-xl tracking-[0.5em] shadow-sm"
                disabled={loading}
              />
            </div>

            <div className="flex justify-center gap-3">
              {[...Array(6)].map((_, i) => (
                <div
                  key={i}
                  className={`w-2.5 h-2.5 rounded-full transition-all duration-200 ${
                    i < pin.length ? 'bg-blue-600 scale-110' : 'bg-gray-200'
                  }`}
                />
              ))}
            </div>

            {error && (
              <div className="flex items-start gap-3 bg-red-50 border border-red-100 rounded-xl px-4 py-3">
                <span className="text-red-500 text-sm mt-0.5">⚠</span>
                <p className="text-sm text-red-600">{error}</p>
              </div>
            )}

            <button
              type="submit"
              disabled={loading || pin.length !== 6 || !employeeId}
              className="w-full bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 disabled:text-gray-400 text-white font-semibold py-3.5 rounded-xl transition-all duration-200 text-base shadow-sm hover:shadow-md"
            >
              {loading ? (
                <span className="flex items-center justify-center gap-2">
                  <svg
                    className="animate-spin w-4 h-4"
                    viewBox="0 0 24 24"
                    fill="none"
                  >
                    <circle
                      className="opacity-25"
                      cx="12"
                      cy="12"
                      r="10"
                      stroke="currentColor"
                      strokeWidth="4"
                    />
                    <path
                      className="opacity-75"
                      fill="currentColor"
                      d="M4 12a8 8 0 018-8v8z"
                    />
                  </svg>
                  กำลังเข้าสู่ระบบ...
                </span>
              ) : (
                'เข้าสู่ระบบ'
              )}
            </button>
          </form>

          <p className="text-center text-sm text-gray-400 mt-8">
            ลืม PIN? ติดต่อ{' '}
            <span className="text-blue-600 font-medium">ฝ่าย HR</span>
          </p>
        </div>
      </div>
    </div>
  );
}
